with j as (select * from jsonb_to_recordset($law7d0062$[{"code_id":"NK_RF","article_number":"64","version_date":"2000-07-31","article_text":"1. Отсрочка или рассрочка предоставляется при наличии оснований, предусмотренных настоящей статьей, на срок, для отсрочек не превышающий одного года либо для рассрочек не превышающий трех лет, соответственно с единовременной или поэтапной уплатой суммы задолженности и (или) налогов, сборов, страховых взносов, срок уплаты которых не наступил на день принятия уполномоченным органом решения в соответствии с пунктом 9 настоящей статьи, на которую предоставляется отсрочка или рассрочка (далее в настоящей статье - сумма отсрочки или рассрочки), если иное не предусмотрено настоящим Кодексом.\n\nВ случае вступления в силу решения о предоставлении отсрочки или рассрочки в соответствии с пунктом 10 настоящей статьи срок, на который предоставляется отсрочка или рассрочка, исчисляется: (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\nс даты принятия уполномоченным органом решения о предоставлении отсрочки или рассрочки - в отношении задолженности;\n\nс установленного срока уплаты соответствующего налога, сбора, страхового взноса - в отношении налогов, сборов, страховых взносов, срок уплаты которых не наступил на день принятия уполномоченным органом решения в соответствии с пунктом 9 настоящей статьи.\n\n2. Отсрочка или рассрочка может быть предоставлена заинтересованному лицу, финансовое положение которого не позволяет уплатить налоги, сборы, страховые взносы, пени, штрафы, проценты в установленный срок, однако имеются достаточные основания полагать, что возможность их уплаты этим лицом возникнет в течение срока, на который предоставляется отсрочка или рассрочка, при наличии хотя бы одного из следующих оснований:\n\n1) причинение этому лицу ущерба в результате стихийного бедствия, технологической катастрофы;\n\n2) непредоставление (несвоевременное предоставление) бюджетных ассигнований и (или) лимитов бюджетных обязательств заинтересованному лицу и (или) недоведение (несвоевременное доведение) предельных объемов финансирования расходов до заинтересованного лица - получателя бюджетных средств в объеме, достаточном для своевременной уплаты налогов, сборов, страховых взносов, а также неперечисление (несвоевременное перечисление) заинтересованному лицу из бюджета денежных средств в объеме, достаточном для своевременной уплаты этим лицом налогов, сборов, страховых взносов, в том числе в счет оплаты оказанных этим лицом услуг (выполненных работ, поставленных товаров) для государственных, муниципальных нужд;\n\n3) угроза возникновения признаков несостоятельности (банкротства) заинтересованного лица в случае единовременной уплаты им налога, сбора, страхового взноса, пеней, штрафов, процентов;\n\n4) имущественное положение физического лица (без учета имущества, на которое в соответствии с законодательством Российской Федерации не может быть обращено взыскание) исключает возможность единовременной уплаты налога, сбора, страхового взноса, пеней, штрафов, процентов;\n\n5) производство и (или) реализация товаров, работ или услуг заинтересованным лицом носит сезонный характер;\n\n6) наличие оснований для предоставления отсрочки или рассрочки по уплате налогов и (или) сборов, подлежащих уплате в связи с перемещением товаров через таможенную границу Евразийского экономического союза, установленных правом Евразийского экономического союза и законодательством Российской Федерации о таможенном регулировании;\n\n7) невозможность единовременной уплаты сумм налогов, сборов, страховых взносов, пеней, штрафов, процентов, подлежащих уплате в бюджетную систему Российской Федерации по результатам налоговой проверки, определяемая в порядке, предусмотренном пунктом 5 настоящей статьи.\n\n3. Если отсрочка или рассрочка предоставлена по основаниям, указанным в подпунктах 3, 4 и 5 пункта 2 настоящей статьи, на сумму отсрочки или рассрочки начисляются проценты исходя из ставки, равной одной второй ключевой ставки Центрального банка Российской Федерации, действовавшей за период отсрочки или рассрочки по уплате налога и (или) сбора, если иное не предусмотрено правом Евразийского экономического союза и законодательством Российской Федерации о таможенном регулировании в отношении налогов и (или) сборов, подлежащих уплате в связи с перемещением товаров через таможенную границу Евразийского экономического союза.\n\nЕсли отсрочка или рассрочка предоставлена по основаниям, указанным в подпунктах 1 и 2 пункта 2 настоящей статьи, на сумму отсрочки или рассрочки проценты не начисляются.\n\nВ случае, если рассрочка предоставлена по основанию, указанному в подпункте 7 пункта 2 настоящей статьи, на сумму рассрочки начисляются проценты исходя из ставки, равной ключевой ставке Центрального банка Российской Федерации, действовавшей в период действия рассрочки, если иное не предусмотрено правом Евразийского экономического союза и законодательством Российской Федерации о таможенном регулировании в отношении налогов и (или) сборов, подлежащих уплате в связи с перемещением товаров через таможенную границу Евразийского экономического союза.\n\nПодлежащие уплате проценты, предусмотренные настоящим пунктом, рассчитываются за каждый календарный день действия отсрочки или рассрочки начиная со дня вступления в силу решения о предоставлении отсрочки или рассрочки в процентах годовых. Проценты, предусмотренные настоящим пунктом, подлежат уплате не позднее дня, следующего за днем уплаты последнего платежа, предусмотренного решением о предоставлении отсрочки или рассрочки. (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\n4. Заявление о предоставлении отсрочки или рассрочки представляется заинтересованным лицом в соответствующий уполномоченный орган. К заявлению о предоставлении отсрочки или рассрочки прилагаются следующие документы:\n\n1) справки банков о ежемесячных оборотах денежных средств (электронных денежных средств, драгоценных металлов), справки оператора платформы цифрового рубля о ежемесячных оборотах цифровых рублей за каждый месяц из предшествующих месяцу подачи указанного заявления трех месяцев по всем счетам этого лица в банках, счету цифрового рубля (при наличии счета цифрового рубля), в том числе з\n\nакрытым в указанный период, при обращении с заявлением о предоставлении отсрочки или рассрочки по основаниям, указанным в подпункте 4 или 7 пункта 2 настоящей статьи, справки банков о наличии его расчетных документов, помещенных в соответствующую картотеку неоплаченных расчетных документов, с раскрытием содержащейся в них информации либо об их отсутствии в этой картотеке на всех счетах этого лица в банках; (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\n2) справки банков об остатках денежных средств (электронных денежных средств, драгоценных металлов) на всех счетах этого лица в банках, справки оператора платформы цифрового рубля об остатках цифровых рублей на счете цифрового рубля (при наличии счета цифрового рубля) при обращении с заявлением о предоставлении отсрочки или рассрочки по основанию, указанному в подпункте 4 пункта 2 настоящей статьи; (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\n3) перечень контрагентов - дебиторов этого лица с указанием цен договоров, заключенных с соответствующими контрагентами - дебиторами, и сроков их исполнения. Заинтересованное лицо вправе предоставить аналогичную информацию об иных обязательствах и основаниях их возникновения;\n\n4) документы, подтверждающие наличие оснований предоставления отсрочки или рассрочки, указанные в пункте 5 настоящей статьи.\n\n5. К заявлению о предоставлении отсрочки или рассрочки по основанию, указанному в подпункте 1 пункта 2 настоящей статьи, прилагается акт оценки причиненного заинтересованному лицу ущерба в результате стихийного бедствия или технологической катастрофы, составленный органом исполнительной власти, органом местного самоуправления или органом публичной власти федеральной территории \"Сириус\", уполномоченным в области гражданской обороны, защиты населения и территорий от чрезвычайных ситуаций.\n\nК заявлению о предоставлении отсрочки или рассрочки заинтересованному лицу - получателю бюджетных средств по основанию, указанному в подпункте 2 пункта 2 настоящей статьи, также прилагается документ финансового органа и (или) главного распорядителя (распорядителя) бюджетных средств, содержащий сведения о сумме бюджетных ассигнований и (или) лимитов бюджетных обязательств, которые не предоставлены (несвоевременно предоставлены) указанному лицу, и (или) о сумме предельных объемов финансирования расходов, которые не доведены (несвоевременно доведены) до этого лица в объеме, достаточном для своевременного исполнения им обязанности по уплате налога, сбора, страхового взноса, пеней, штрафов, процентов.\n\nК заявлению о предоставлении отсрочки или рассрочки по основанию, указанному в подпункте 2 пункта 2 настоящей статьи, заинтересованному лицу - получателю бюджетных средств, которому не перечислены (несвоевременно перечислены) денежные средства из бюджета в объеме, достаточном для своевременного исполнения им обязанности по уплате налога, сбора, страхового взноса, пеней, штрафов, процентов, в том числе в счет оказанных этим лицом услуг (выполненных работ, поставленных товаров) для государственных, муниципальных нужд, нужд федеральной территории \"Сириус\", также прилагается документ получателя бюджетных средств либо документ государственного, муниципального заказчика, уполномоченного органа публичной власти федеральной территории \"Сириус\" в сфере закупок для обеспечения нужд федеральной территории \"Сириус\", содержащие сведения о сумме денежных средств, которая не перечислена (несвоевременно перечислена) этому лицу из бюджета в объеме, достаточном для своевременного исполнения им обязанности по уплате налога, сбора, страхового взноса, пеней, штрафов, процентов, в том числе в счет оплаты оказанных таким лицом услуг (выполненных работ, поставленных товаров) для государственных, муниципальных нужд, нужд федеральной территории \"Сириус\".\n\nНаличие основания, указанного в подпункте 3 пункта 2 настоящей статьи, устанавливается на дату подачи заявления о предоставлении отсрочки или рассрочки по результатам анализа финансового состояния хозяйствующего субъекта, проведенного органом, уполномоченным в соответствии со статьей 63 настоящего Кодекса принимать решения об отсрочке или рассрочке, в соответствии с методикой, утверждаемой федеральным органом исполнительной власти, уполномоченным осуществлять функции по выработке государственной политики и нормативно-правовому регулированию в сфере несостоятельности (банкротства) и финансового оздоровления.\n\nК заявлению о предоставлении отсрочки или рассрочки по основанию, указанному в подпункте 4 пункта 2 настоящей статьи, также прилагаются сведения о движимом и недвижимом имуществе физического лица (за исключением имущества, на которое в соответствии с законодательством Российской Федерации не может быть обращено взыскание).\n\nК заявлению о предоставлении отсрочки или рассрочки по основанию, указанному в подпункте 5 пункта 2 настоящей статьи, также прилагается составленный заинтересованным лицом документ, подтверждающий, что в общем доходе от реализации товаров (работ, услуг) такого лица доля его дохода от отраслей и видов деятельности, включенных в утверждаемый Правительством Российской Федерации перечень отраслей и видов деятельности, имеющих сезонный характер, составляет не менее 50 процентов.\n\nНаличие указанного в подпункте 7 пункта 2 настоящей статьи основания для предоставления рассрочки устанавливается уполномоченным органом в случае, если сумма поступлений денежных средств на счета заинтересованного лица в банках за трехмесячный период, предшествующий подаче заявления о предоставлении рассрочки, меньше суммы краткосрочных обязательств заинтересованного лица (с учетом подлежащих уплате в бюджетную систему Российской Федерации по результатам налоговой проверки сумм налога, сбора, страхового взноса, пеней, штрафов, процентов), уменьшенной на величину доходов будущих периодов, по сведениям представленной в установленном порядке в налоговый орган бухгалтерской (финансовой) отчетности на последнюю отчетную дату, при соблюдении предусмотренных настоящим пунктом условий.\n\nРассрочка по основанию, указанному в подпункте 7 пункта 2 настоящей статьи, может быть предоставлена заинтересованному лицу в случае подачи им соответствующего заявления о предоставлении рассрочки не позднее 10 дней после вступления в силу решения по результатам налоговой проверки, а также в случае, если это заинтересованное лицо одновременно удовлетворяет следующим условиям:\n\nсо дня создания организации, регистрации физического лица в качестве индивидуального предпринимателя до дня представления в уполномоченный орган заявления о предоставлении рассрочки прошло не менее одного года;\n\nорганизация не находится в процессе реорганизации или ликвидации.\n\n6. При обращении заинтересованного лица с заявлением о предоставлении отсрочки или рассрочки представляются договор залога имущества или договор поручительства либо банковская гарантия, если иное не предусмотрено настоящим Кодексом.\n\nПри обращении заинтересованного лица с заявлением о предоставлении рассрочки по основанию, указанному в подпункте 7 пункта 2 настоящей статьи, в качестве способа обеспечения исполнения обязанности по уплате налога, сбора, страховых взносов, пеней, штрафов, процентов указанным лицом представляется банковская гарантия. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nУказанная в настоящем пункте банковская гарантия может быть представлена за налогоплательщика гарантом. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nТребования к банковской гарантии и порядок ее представления гарантом устанавливаются в соответствии со статьей 741 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nПо ходатайству заинтересованного лица уполномоченный орган вправе принять решение о временном (на период рассмотрения заявления о предоставлении отсрочки или рассрочки и до вступления решения о предоставлении отсрочки или рассрочки в силу (наступления обстоятельств, указанных в абзаце седьмом пункта 10 настоящей статьи) или до отказа в предоставлении отсрочки или рассрочки) приостановлении уплаты суммы задолженности, указанной в этом заявлении заинтересованного лица. (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\nВ случае необходимости запроса, в том числе у иных лиц, дополнительной информации в ходе рассмотрения заявления заинтересованного лица о предоставлении отсрочки или рассрочки уполномоченный орган вправе приостановить срок принятия решения о предоставлении отсрочки или рассрочки, но не более чем на 20 календарных дней, о чем выносится соответствующее решение, о принятии которого уведомляется заинтересованное лицо в трехдневный срок с даты его принятия.\n\nНе подлежит рассмотрению заявление заинтересованного лица о предоставлении отсрочки или рассрочки, представленное в уполномоченный орган:\n\nбез указания основания для предоставления отсрочки или рассрочки, предусмотренного пунктом 2 настоящей статьи, суммы задолженности и (или) налогов, сборов, страховых взносов, срок уплаты которых не наступил на день принятия уполномоченным органом решения об отсрочке или рассрочке, и срока, на который запрашивается отсрочка или рассрочка;\n\nбез приложения документов, указанных в пункте 4 настоящей статьи;\n\nналоговым агентом без учета положений пункта 9 статьи 61 настоящего Кодекса.\n\nДнем вступления в силу решения о предоставлении отсрочки или рассрочки является:\n\nдень его принятия в случае заключения договора залога имущества, договора поручительства либо предоставления банковской гарантии до дня принятия решения о предоставлении отсрочки или рассрочки;\n\nдень заключения договора залога имущества, договора поручительства или предоставления банковской гарантии в случае заключения указанных договоров либо предоставления банковской гарантии в срок не позднее 30 дней со дня принятия решения об отсрочке или рассрочке;\n\nдень получения уполномоченным органом информации о согласовании решения об отсрочке или рассрочке финансовыми органами соответствующих субъектов Российской Федерации, муниципальных образований, федеральной территории \"Сириус\" в соответствии с пунктом 2 статьи 63 настоящего Кодекса. При отсутствии в уполномоченном органе информации об отказе в согласовании соответствующего решения в течение 10 дней со дня его принятия решение о предоставлении отсрочки или рассрочки считается согласованным в день, следующий за днем истечения установленного для согласования срока.\n\nРешение о предоставлении отсрочки или рассрочки в случае необходимости его согласования (полностью или частично) с финансовыми органами соответствующих субъектов Российской Федерации, муниципальных образований, федеральной территории \"Сириус\" в соответствии с пунктом 2 статьи 63 настоящего Кодекса не может вступить в силу ранее дня получения уполномоченным органом соответствующего согласования в установленной части. Срок согласования (отказа в согласовании) не должен превышать 10 дней со дня получения финансовыми органами соответствующих субъектов Российской Федерации, муниципальных образований, федеральной территории \"Сириус\" решений уполномоченных органов в установленной части. При отсутствии в уполномоченном органе информации о согласовании (отказе в согласовании) соответствующего решения указанными органами власти принятое решение о предоставлении отсрочки или рассрочки считается согласованным в день, следующий за днем истечения установленного для согласования срока.\n\nПри отсутствии в течение 30 календарных дней, следующих за днем принятия решения о предоставлении отсрочки или рассрочки, заключенных договора залога имущества в соответствии со статьей 73 настоящего Кодекса, договора поручительства в соответствии со статьей 74 настоящего Кодекса, предоставленной банковской гарантии в соответствии со статьей 741 настоящего Кодекса либо отказе в согласовании (полностью или частично) финансовыми органами субъектов Российской Федерации, муниципальных образований, федеральной территории \"Сириус\" в соответствии с пунктом 2 статьи 63 настоящего Кодекса соответствующее решение о предоставлении отсрочки или рассрочки не вступает в силу. Информация о невступлении решения о предоставлении отсрочки или рассрочки в силу доводится до заинтересованного лица в трехдневный срок с даты истечения соответствующего срока либо получения отказа в согласовании финансовыми органами субъектов Российской Федерации, муниципальных образований, федеральной территории \"Сириус\" в соответствии с пунктом 2 статьи 63 настоящего Кодекса.\n\nОтказ уполномоченного органа в предоставлении отсрочки или рассрочки может быть обжалован заинтересованным лицом в порядке, установленном законодательством Российской Федерации.\n\nНормативными правовыми актами представительного органа федеральной территории \"Сириус\" могут быть установлены дополнительные основания и иные условия предоставления отсрочки и рассрочки по уплате в федеральной территории \"Сириус\" местных налогов и (или) сборов.\n\n(Статья в редакции  Федерального закона от 14.07.2022 № 263-ФЗ)","article_title":"Статья 64. Порядок и условия предоставления отсрочки или рассрочки","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ce3638a3df90af017974a08f5060b9584d435ce980fa3022565570117c08091d"},{"code_id":"NK_RF","article_number":"64.1","version_date":"2000-07-31","article_text":"(Дополнение статьей - Федеральный закон от 26.11.2008 № 224-ФЗ) (Утратила силу - Федеральный закон от 08.03.2015 № 49-ФЗ)","article_title":"Статья 64.1. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5889e5cecda1285b8b7783826c9f31e2356e12344283b7c0497959b90d92f7b1"},{"code_id":"NK_RF","article_number":"65","version_date":"2000-07-31","article_text":"(Статья утратила силу - Федеральный закон от 27.07.2006 № 137-ФЗ)","article_title":"Статья 65. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"874e85b038eba45ec46f4c9aa648a494e0dd2d12f41eef16117bed6c09a151a9"},{"code_id":"NK_RF","article_number":"66","version_date":"2000-07-31","article_text":"Инвестиционный налоговый кредит может быть предоставлен по налогу на прибыль организации, а также по региональным и местным налогам. (В редакции Федерального закона от 27.07.2006 № 137-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 29.07.2004 № 95-ФЗ)\n\nИнвестиционный налоговый кредит может быть предоставлен на срок от одного года до пяти лет.\n\nАбзац. (Дополнение абзацем - Федеральный закон от 03.12.2011 № 392-ФЗ) (Утратил силу - Федеральный закон от 23.11.2024 № 393-ФЗ)\n\nУменьшение производится по каждому платежу соответствующего налога, по которому предоставлен инвестиционный налоговый кредит, за каждый отчетный период до тех пор, пока сумма, не уплаченная организацией в результате всех таких уменьшений (накопленная сумма кредита), не станет равной сумме кредита, предусмотренной соответствующим договором. Конкретный порядок уменьшения налоговых платежей определяется заключенным договором об инвестиционном налоговом кредите. (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\nЕсли организацией заключено более одного договора об инвестиционном налоговом кредите, срок действия которых не истек к моменту очередного платежа по налогу, накопленная сумма кредита определяется отдельно по каждому из этих договоров. При этом увеличение накопленной суммы кредита производится вначале в отношении первого по сроку заключения договора, а при достижении этой накопленной суммой кредита размера, предусмотренного указанным договором, организация может увеличивать накопленную сумму кредита по следующему договору.\n\nЕсли организация имела убытки по результатам отдельных отчетных периодов в течение налогового периода либо убытки по итогам всего налогового периода, излишне накопленная по итогам налогового периода сумма кредита переносится на следующий налоговый период и признается накопленной суммой кредита в первом отчетном периоде нового налогового периода. (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)","article_title":"Статья 66. Инвестиционный налоговый кредит","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5b27e4c1b9d0e3b3fe1e078f7d16aa9c08b995e451926ff6485ba4791003f50c"},{"code_id":"NK_RF","article_number":"67","version_date":"2000-07-31","article_text":"1. Инвестиционный налоговый кредит может быть предоставлен организации, являющейся налогоплательщиком соответствующего налога, при наличии хотя бы одного из следующих оснований:\n\n1) проведение этой организацией научно-исследовательских или опытно-конструкторских работ либо технического перевооружения собственного производства, в том числе направленного на создание рабочих мест для инвалидов и (или) повышение энергетической эффективности производства товаров, выполнения работ, оказания услуг, или осуществление мероприятия или мероприятий по снижению негативного воздействия на окружающую среду, предусмотренных пунктом 4 статьи 17 Федерального закона от 10 января 2002 года № 7-ФЗ \"Об охране окружающей среды\"; (В редакции федеральных законов от 23.11.2009 № 261-ФЗ; от 21.07.2014 № 219-ФЗ)\n\n2) осуществление этой организацией внедренческой или инновационной деятельности, в том числе создание новых или совершенствование применяемых технологий, создание новых видов сырья или\n\nматериалов;\n\n3) выполнение этой организацией особо важного заказа по социально-экономическому развитию региона или предоставление ею особо важных услуг населению;\n\n4) выполнение организацией государственного оборонного заказа; (Дополнение подпунктом - Федеральный закон от 26.11.2008 № 224-ФЗ)\n\n5) осуществление этой организацией инвестиций в создание объектов, имеющих наивысший класс энергетической эффективности, в том числе многоквартирных домов, и (или) относящихся к возобновляемым источникам энергии, и (или) относящихся к объектам по производству тепловой энергии, электрической энергии, имеющим коэффициент полезного действия более чем 57 процентов, и (или) иных объектов, технологий, имеющих высокую энергетическую эффективность, в соответствии с перечнем, утвержденным Правительством Российской Федерации; (Дополнение подпунктом - Федеральный закон от 23.11.2009 № 261-ФЗ)\n\n6) (Дополнение подпунктом - Федеральный закон от 03.12.2011 № 392-ФЗ) (Утратил силу - Федеральный закон от 23.11.2024 № 393-ФЗ)\n\n2. Инвестиционный налоговый кредит предоставляется:\n\n1) по основаниям, указанным в подпунктах 1 и 5 пункта 1 настоящей статьи, - на сумму кредита, составляющую 100 процентов стоимости приобретенного заинтересованной организацией оборудования, используемого исключительно для перечисленных в этих подпунктах целей; (В редакции федеральных законов от 23.11.2009 № 261-ФЗ; от 27.07.2010 № 229-ФЗ; от 23.07.2013 № 248-ФЗ)\n\n2) по основаниям, указанным в подпунктах 2 - 4 пункта 1 настоящей статьи, - на суммы кредита, определяемые по соглашению между уполномоченным органом и заинтересованной организацией; (В редакции Федерального закона от 26.11.2008 № 224-ФЗ)\n\n3) (Дополнение подпунктом - Федеральный закон от 03.12.2011 № 392-ФЗ) (Утратил силу  - Федеральный закон от 23.11.2024 № 393-ФЗ)\n\n3. Основания для получения инвестиционного налогового кредита должны быть документально подтверждены заинтересованной организацией.\n\nФорма договора об инвестиционном налоговом кредите устанавливается уполномоченным органом принимающим решение о предоставлении инвестиционного налогового кредита. (В редакции Федерального закона от 29.07.2004 № 95-ФЗ)\n\nАбзац. (Дополнение абзацем - Федеральный закон от 27.07.2010 № 229-ФЗ) (Утратил силу - Федеральный закон от 23.07.2013 № 248-ФЗ)\n\nАбзац. (Дополнение абзацем - Федеральный закон от 03.12.2011 № 392-ФЗ) (Утратил силу - Федеральный закон от 23.11.2024 № 393-ФЗ)\n\nДоговор об инвестиционном налоговом кредите должен содержать положения, в соответствии с которыми не допускаются в течение срока его действия реализация или передача во владение, пользование или распоряжение другим лицам оборудования или иного имущества, приобретение которого организацией явилось условием для предоставления инвестиционного налогового кредита, либо определяются условия такой реализации (передачи).\n\nНе допускается устанавливать проценты на сумму кредита по ставке, менее одной второй и превышающей три четвертых ставки рефинансирования Центрального банка Российской Федерации. (В редакции  федеральных законов от 03.12.2011 № 392-ФЗ, от 23.11.2024 № 393-ФЗ)\n\nАбзац. (Дополнение абзацем - Федеральный закон от 03.12.2011 № 392-ФЗ) (Утратил силу - Федеральный закон от 23.11.2024 № 393-ФЗ)\n\nКопия договора представляется организацией в налоговый орган по месту ее учета в пятидневный срок со дня заключения договора.\n\nНормативными правовыми актами представительного органа федеральной территории \"Сириус\" о местных налогах, подлежащих уплате в федеральной территории \"Сириус\", могут быть установлены иные основания и условия предоставления инвестиционного налогового кредита, включая сроки действия инвестиционного налогового кредита и ставки процентов на сумму кредита. (Дополнение абзацем - Федеральный закон от 11.06.2021 № 199-ФЗ)\n\n(Пункт в редакции Федерального закона от 30.03.2012 № 19-ФЗ)","article_title":"Статья 67. Порядок и условия предоставления инвестиционного налогового кредита","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fef7951f5c8bbc92264b4e55b14cec780ac83a90bb0c01f584e471e23c4bd0e7"},{"code_id":"NK_RF","article_number":"68","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 27.07.2006 № 137-ФЗ)\n\nПри этом оставшаяся неуплаченной сумма задолженности определяется как разница между суммой задолженности, определенной в решении о предоставлении отсрочки (рассрочки), увеличенной на сумму процентов, исчисленную в соответствии с таким решением о предоставлении отсрочки или рассрочки начиная со дня вступления в силу решения о предоставлении отсрочки или рассрочки за период действия отсрочки (рассрочки), и фактически уплаченными суммами и процентами. (В редакции  федеральных законов от 14.07.2022 № 263-ФЗ, от 08.08.2024 № 259-ФЗ)\n\n(Наименование в редакции Федерального закона от 03.07.2016 № 243-ФЗ)","article_title":"Статья 68. Прекращение действия отсрочки, рассрочки или инвестиционного налогового кредита","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"071e285286b426442a23badd35c08f657db7dc51160080ffa43dd2b6ed06e3fe"},{"code_id":"NK_RF","article_number":"69","version_date":"2000-07-31","article_text":"1. Неисполнение обязанности по уплате налогов, авансовых платежей по налогам, сборов, страховых взносов, пеней, штрафов, процентов, повлекшее формирование отрицательного сальдо единого налогового счета налогоплательщика, является основанием для направления налоговым органом налогоплательщику требования об уплате задолженности.\n\nТребованием об уплате задолженности признается извещение налогоплательщика о наличии отрицательного сальдо единого налогового счета и сумме задолженности с указанием налогов, авансовых платежей по налогам, сборов, страховых взносов, пеней, штрафов, процентов на момент направления требования, а также об обязанности уплатить в установленный срок сумму задолженности.\n\nПосле восстановления учета на едином налоговом счете сумм, ранее не учтенных в совокупной обязанности в соответствии с подпунктами 2 - 34, 5 и 6 пункта 7 статьи 113 настоящего Кодекса, новое требование об уплате задолженности не направляется. (Дополнение абзацем - Федеральный закон от 31.07.2025 № 287-ФЗ)\n\n2. Требование об уплате задолженности также должно содержать:\n\nсведения о сроке исполнения требования;\n\nсведения о мерах по взысканию задолженности и обеспечению исполнения обязанности по уплате налога, авансовых платежей, сборов, страховых взносов, пеней, штрафов, процентов, которые будут применены в случае неисполнения требования налогоплательщиком;\n\nпредупреждение об обязанности налогового органа в соответствии с пунктом 3 статьи 32 настоящего Кодекса направить материалы в следственные органы для решения вопроса о возбуждении уголовного дела (в случае, если размер недоимки позволяет предполагать факт совершения нарушения законодательства о налогах и сборах, содержащего признаки преступления).\n\n3. Требование об уплате задолженности должно быть исполнено в течение восьми дней с даты получения указанного требования, если более продолжительный период времени для уплаты задолженности не указан в этом требовании.\n\nИсполнением требования об уплате задолженности признается уплата (перечисление) суммы задолженности в размере отрицательного сальдо на дату исполнения.\n\nФорматы и порядок направления налогоплательщику требования об уплате задолженности в электронной форме по телекоммуникационным каналам связи устанавливаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Статья в редакции  Федерального закона от 14.07.2022 № 263-ФЗ)","article_title":"Статья 69. Требование об уплате задолженности","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"72d4b044939712aa0cfd8c9fac5c5a6b96a674fd72cd79d37f3b2fcbbad8af5a"},{"code_id":"NK_RF","article_number":"7","version_date":"2000-07-31","article_text":"Лицом, имеющим фактическое право на доходы, в целях настоящего Кодекса также признается лицо (иностранная структура без образования юридического лица), в интересах которого иное лицо (иная иностранная структура без образования юридического лица) правомочно распоряжаться доходом, полученным организацией (иностранной структурой без образования юридического лица), указанной в абзаце первом настоящего пункта, или непосредственно таким иным лицом (иной иностранной структурой без образования юридического лица).\n\nПри определении лица, имеющего фактическое право на доходы, учитываются функции, выполняемые лицами, указанными в настоящем пункте (иностранными структурами без образования юридического лица), а также принимаемые ими риски. При этом наличие фактического права на доходы определяется применительно к каждой отдельной выплате дохода в виде дивидендов и (или) к группе выплат дохода в рамках одного договора. (В редакции Федерального закона от 27.11.2018 № 424-ФЗ)\n\n(Пункт в редакции Федерального закона от 15.02.2016 № 32-ФЗ)\n\n1) в случае, если лицо, имеющее фактическое право на выплачиваемые доходы (их часть), признается в соответствии с настоящим Кодексом налоговым резидентом Российской Федерации, налогообложение выплачиваемого дохода (его части) производится в соответствии с положениями соответствующих глав части второй настоящего Кодекса для налогоплательщиков, являющихся налоговыми резидентами Российской Федерации, без удержания соответствующего налога в отношении выплачиваемых доходов (их части) у источника выплаты при условии информирования налогового органа по месту постановки на учет организации - источника выплаты доходов в порядке, устанавливаемом федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов;\n\n2) в случае, если лицо, имеющее фактическое право на выплачиваемые доходы (их часть), является иностранным лицом, на которое распространяется действие международного договора Российской Федерации по вопросам налогообложения, положения указанного международного договора Российской Федерации применяются в отношении лица, которое имеет фактическое право на выплачиваемые доходы (их часть) в соответствии с порядком, предусмотренным ме\n\nждународным договором Российской Федерации;\n\n3) в случае, если лицо, имеющее фактическое право на выплачиваемые доходы (их часть), является иностранным лицом, на которое не распространяется действие международного договора Российской Федерации по вопросам налогообложения, налогообложение выплачиваемого дохода (его части) производится в соответствии с положениями соответствующих глав части второй настоящего Кодекса. (Дополнение подпунктом - Федеральный закон от 27.11.2018 № 424-ФЗ)\n\n(Статья в редакции Федерального закона от 24.11.2014 № 376-ФЗ)","article_title":"Статья 7. Международные договоры по вопросам налогообложения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"92df1683b8801e8137502358c56e3422ad815515295bfffbfedb81d172953e55"},{"code_id":"NK_RF","article_number":"70","version_date":"2000-07-31","article_text":"(Статья в редакции  Федерального закона от 14.07.2022 № 263-ФЗ)","article_title":"Статья 70. Сроки направления требования об уплате задолженности","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"72d589278950508aa45731c7f3970dd158a1f96440114ce1054aa0314e45ba54"},{"code_id":"NK_RF","article_number":"71","version_date":"2000-07-31","article_text":"(Статья утратила силу  - Федеральный закон от 14.07.2022 № 263-ФЗ)\n\n(Наименование в редакции Федерального закона от 03.07.2016 № 243-ФЗ)","article_title":"Статья 71. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5fcb4ee6466ef86651b2fcc6c26fb3453d0d9a72209cc78b369c7ab236db31ee"},{"code_id":"NK_RF","article_number":"72","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\nАбзац. (Утратил силу - Таможенный кодекс Российской Федерации от 28.05.2003 № 61-ФЗ)\n\nСведения, предусмотренные настоящим пунктом, размещаются в течение трех дней со дня принятия соответствующего решения налогового органа, но не ранее вступления в силу решения о привлечении к ответственности за совершение налогового правонарушения или решения об отказе в привлечении к ответственности за совершение налогового правонарушения, исполнение которого обеспечено запретом на отчуждение (передачу в залог) имущества налогоплательщика без согласия налогового органа в соответствии с пунктом 10 статьи 101 настоящего Кодекса.\n\nСостав размещаемых сведений и порядок их размещения утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Дополнение пунктом - Федеральный закон от 29.09.2019 № 325-ФЗ)","article_title":"Статья 72. Способы обеспечения исполнения обязанности по уплате налогов, сборов, страховых взносов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4d01417a99542b0bf0e116e3f8fd17503816034176faff79a015bfcc97b1a78b"},{"code_id":"NK_RF","article_number":"73","version_date":"2000-07-31","article_text":"При оформлении договора залога залогодателем может быть как сам налогоплательщик, плательщик сбора или плательщик страховых взносов, так и третье лицо.\n\nФорма договора залога утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n(Пункт в редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\nого обеспечено запретом на отчуждение (передачу в залог) имущества налогоплательщика (плательщика сбора, плательщика страховых взносов, налогового агента) без согласия налогового органа, имущество, в отношении которого применен указанный в настоящем пункте способ обеспечения исполнения обязанности по уплате налогов (сборов, страховых взносов) или принята обеспечительная мера, признается находящимся в залоге у налогового органа на основании закона. (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\nЗалог, возникающий в соответствии с настоящим пунктом в отношении имущества, находящегося в залоге у третьих лиц, признается последующим залогом.\n\nЗалог в соответствии с настоящим пунктом не возникает в отношении имущества, находящегося к моменту наступления указанных в настоящем Кодексе обстоятельств, влекущих возникновение залога, в залоге у третьих лиц, если по правилам гражданского законодательства Российской Федерации передача такого имущества в последующий залог не допускается.\n\nВ случае возникновения залога у налогового органа на основании закона предусмотренные гражданским законодательством Российской Федерации последствия залога не распространяются на денежные средства на счетах, вкладах (депозитах), предназначенные для удовлетворения требований в соответствии с гражданским законодательством Российской Федерации, которые предшествуют исполнению обязанности по уплате налогов (сборов, страховых взносов).\n\nЗалог, возникающий в соответствии с настоящим пунктом, подлежит государственной регистрации и учету в соответствии с правилами, предусмотренными гражданским законодательством Российской Федерации.\n\n(Дополнение пунктом - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\nПредметом залога по договору между налоговым органом и залогодателем не может быть предмет залога по другому договору.","article_title":"Статья 73. Залог имущества","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2d5e82eb30d08e388443d88236d16bb1dccbeea23c1072ed8ba608a547ce4568"},{"code_id":"NK_RF","article_number":"74","version_date":"2000-07-31","article_text":"Поручительство оформляется в соответствии с гражданским законодательством Российской Федерации договором между налоговым органом и поручителем по форме, утверждаемой федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (В редакции Федерального закона от 30.11.2016 № 401-ФЗ)\n\nВ случае неуплаты или неполной уплаты в установленный срок налога, обязанность по уплате которого обеспечена поручительством, налоговый орган в течение тридцати дней со дня возникновения задолженности в связи с неисполнением такой обязанности направляет поручителю требование об уплате денежной суммы по договору поручительства. (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\nНалоговый орган применяет меры по взысканию с поручителя сумм, обязанность по уплате которых обеспечена поручительством, в порядке и сроки, которые предусмотрены статьями 46 - 48 настоящего Кодекса, в случае неисполнения им в установленный срок требования об уплате денежной суммы по договору поручительства.\n\n(Пункт в редакции Федерального закона от 30.11.2016 № 401-ФЗ)\n\n(Пункт 6 исключен  - Федеральный закон от 09.07.1999 № 154-ФЗ)","article_title":"Статья 74. Поручительство","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"30eb7519c2b80b30707c5c230f6b4c19d306af2e75c1fe4deba56685a604452d"},{"code_id":"NK_RF","article_number":"74.1","version_date":"2000-07-31","article_text":"Банковская гарантия, представляемая в налоговый орган гарантом, подписывается усиленной квалифицированной электронной подписью лица, обладающего таким правом, и направляется в налоговый орган в электронной форме по телекоммуникационным каналам связи. Формат и порядок направления банковской гарантии в налоговый орган в электронной форме утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, по согласованию с Центральным банком Российской Федерации. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nВ случаях, предусмотренных настоящим Кодексом, налоговый орган уведомляет выдавшего банковскую гарантию гаранта в электронной форме по телекоммуникационным каналам связи о его освобождении от обязательств по этой банковской гарантии. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nПри этом налогоплательщика, в отношении которого выдана такая банковская гарантия, налоговый орган уведомляет в электронной форме по телекоммуникационным каналам связи об освобождении гаранта от обязательств по этой банковской гарантии в случае поступления от указанного налогоплательщика в налоговый орган в электронной форме по телекоммуникационным каналам связи соответствующего заявления. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nНалоговый орган возвращает по письменному заявлению налогоплательщика представленную им на бумажном носителе банковскую гарантию в срок не позднее трех дней со дня получения такого заявления. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nВ целях статьи 64 настоящего Кодекса банковская гарантия может быть представлена в налоговый орган налогоплательщиком на бумажном носителе. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n1) наличие лицензии на осуществление банковских операций, выданной Центральным банком Российской Федерации, и осуществление банковской деятельности в течение не менее пяти лет;\n\n2) наличие собственных средств (капитала) банка в размере не менее 1 миллиарда рублей;\n\n3) соблюдение обязательных нормативов, предусмотренных Федеральным законом от 10 июля 2002 года № 86-ФЗ \"О Центральном банке Российской Федерации (Банке России)\", на все отчетные даты в течение последних шести месяцев;\n\n4) отсутствие требования Центрального банка Российской Федерации об осуществлении мер по финансовому оздоровлению банка на основании параграфа 41 главы IX Федерального закона от 26 октября 2002 года № 127-ФЗ \"О несостоятельности (банкротстве)\". Настоящий подпункт не применяется к банкам, в отношении которых реализуются меры по предупреждению банкротства, осуществляемые с участием Центрального банка Российской Федерации или государственной корпорации \"Агентство по страхованию вкладов\". (В редакции федеральных законов от 29.12.2014 № 462-ФЗ, от 27.12.2019 № 470-ФЗ)\n\nМаксимальная сумма одной банковской гарантии и максимальная сумма всех одновременно действующих банковских гарантий, выданных государственной корпорацией развития \"ВЭБ.РФ\", для принятия указанных гарантий налоговыми органами устанавливаются Правительством Российской Федерации. (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 29.12.2017 № 466-ФЗ)\n\nВ течение срока реализации плана по предупреждению банкротства банка, включенного в перечень на дату утверждения Советом директоров Центрального банка Российской Федерации плана по предупреждению банкротства банка, этот банк не исключается из перечня при условии принятия Советом директоров Центрального банка Российской Федерации решения о гарантировании непрерывности деятельности этого банка.\n\nВ случае, если банк, включенный в перечень на дату утверждения в отношении этого банка плана по предупреждению банкротства банка, исключен из перечня до дня принятия Советом директоров Центрального банка Российской Федерации решения о гарантировании непрерывности деятельности этого банка в течение срока реализации плана по предупреждению банкротства банка, этот банк включается Министерством финансов Российской Федерации в перечень не позднее чем в течение пяти дней со дня получения от Центрального банка Российской Федерации сведений, указанных в абзаце первом настоящего пункта.\n\n(Дополнение пунктом - Федеральный закон от 27.12.2019 № 470-ФЗ)\n\n1) банковская гарантия должна быть безотзывной и непередаваемой;\n\n2) банковская гарантия не может содержать указание на представление налоговым органом гаранту документов, которые не предусмотрены настоящей статьей;\n\n3) срок действия банковской гарантии должен истекать не ранее чем через шесть месяцев со дня истечения установленного срока исполнения налогоплательщиком обязанности по уплате налога, обеспеченной банковской гарантией, если иное не предусмотрено настоящим Кодексом;\n\n4) сумма, на которую выдана банковская гарантия, должна обеспечивать исполнение гарантом в полном объеме обязанности налогоплательщика по уплате налога и уплате пеней, если иное не предусмотрено настоящим Кодексом; (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n5) банковская гарантия должна предусматривать применение налоговым органом мер по взысканию с гаранта сумм, обязанность по уплате которых обеспечена банковской гарантией, в порядке и сроки, которые предусмотрены статьями 46 и 47 настоящего Кодекса, в случае неисполнения им в установленный срок требования об уплате денежной суммы по банковской гарантии, направленного до окончания срока действия банковской гарантии.\n\nВ случае неисполнения гарантом в установленный срок требования об уплате денежной суммы по банковской гарантии налоговый орган реализует право бесспорного списания суммы, указанной в данном требовании. (Дополнение абзацем - Федеральный закон от 14.07.2022 № 263-ФЗ) (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nМаксимальная сумма одной банковской гарантии и максимальная сумма всех одновременно действующих банковских гарантий, выданных включенным в перечень банком, в отношении которого Советом директоров Центрального банка Российской Федерации утвержден план по предупреждению банкротства банка и принято решение о гарантировании непрерывности его деятельности в течение срока реализации плана по предупреждению банкротства банка, для принятия указанных гарантий налоговыми органами в течение срока реализации плана по предупреждению банкротства банка устанавливаются в соответствии с абзацем первым настоящего пункта на последнюю квартальную отчетную дату, предшествующую дате утверждения Советом директоров Центрального банка Российской Федерации плана по предупреждению банкротства этого банка. (Дополнение абзацем - Федеральный закон от 27.12.2019 № 470-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 05.04.2016 № 101-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 23.07.2013 № 248-ФЗ)","article_title":"Статья 74.1. Банковская гарантия","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f60aa7d816c842932d47d1eae15f80ebe394ce4010f09dab038b8811078bc338"},{"code_id":"NK_RF","article_number":"75","version_date":"2000-07-31","article_text":"1. Пеней признается установленная настоящей статьей денежная сумма, которую налогоплательщик должен уплатить в бюджетную систему Российской Федерации в случае неисполнения обязанности по уплате причитающихся сумм налогов в установленные законодательством о налогах и сборах сроки.\n\n2. Сумма соответствующих пеней уплачивается дополнительно к причитающимся к уплате суммам налога независимо от применения других мер обеспечения исполнения обязанности по уплате налога, а также мер ответственности за нарушение законодательства о налогах и сборах.\n\n3. Пеня начисляется\n\nза каждый календарный день просрочки исполнения обязанности по уплате налогов начиная со дня возникновения недоимки по день (включительно) исполнения совокупной обязанности по уплате налогов.\n\nНе начисляются пени на сумму недоимки, которую налогоплательщик не мог погасить в силу того, что по решению налогового органа был наложен арест на имущество налогоплательщика или по решению суда были приняты обеспечительные меры в виде приостановления операций по счетам налогоплательщика в банке, наложения ареста на денежные средства или на имущество налогоплательщика. В этом случае пени не начисляются за весь период действия указанных обстоятельств. Подача заявления о предоставлении отсрочки или рассрочки либо заявления о предоставлении инвестиционного налогового кредита не приостанавливает начисления пеней на сумму налога, подлежащую уплате.\n\nНе начисляются пени на сумму недоимки в размере, не превышающем размера положительного сальдо единого налогового счета налогоплательщика в соответствующий календарный день просрочки исполнения обязанности по уплате налогов, увеличенного на сумму денежных средств, зачтенную в счет исполнения предстоящей обязанности этого налогоплательщика по уплате конкретного налога. (Дополнение абзацем - Федеральный закон от 29.10.2024 № 362-ФЗ)\n\n1) для физических лиц, включая индивидуальных предпринимателей, - одной трехсотой действующей в это время ключевой ставки Центрального банка Российской Федерации;\n\n2) для организаций:\n\nв отношении суммы отрицательного сальдо единого налогового счета, сформированного в связи с неисполненной обязанностью по уплате налогов, непрерывно существующей до 30 календарных дней (включительно), - одной трехсотой действующей в это время ключевой ставки Центрального банка Российской Федерации;\n\nв отношении суммы недоимки, не указанной в абзаце втором настоящего подпункта, - одной стопятидесятой ключевой ставки Центрального банка Российской Федерации.\n\n1) в течение первых 30 календарных дней (включительно) просрочки исполнения обязанности по уплате налогов - одной трехсотой ключевой ставки Центрального банка Российской Федерации, действующей в указанный период;\n\n2) начиная с 31-го дня просрочки исполнения обязанности по уплате налогов по 90-й день (включительно) - одной стопятидесятой ключевой ставки Центрального банка Российской Федерации, действующей в указанный период;\n\n3) начиная с 91-го дня просрочки исполнения обязанности по уплате налогов - одной трехсотой ключевой ставки Центрального банка Российской Федерации, действующей в указанный период.\n\n(Дополнение пунктом - Федеральный закон от 29.10.2024 № 362-ФЗ)\n\nВ случае увеличения совокупной обязанности отражение на едином налоговом счете начисления пеней на сумму недоимки осуществляется с даты учета увеличения соответствующей обязанности в соответствии с пунктом 5 статьи 113 настоящего Кодекса.\n\n1) возникшей в результате произведенной налогоплательщиком в соответствии с пунктом 6 статьи 1053 настоящего Кодекса самостоятельной корректировки налоговой базы и суммы налога (убытков), - со дня возникновения недоимки до установленного срока уплаты налога на прибыль организаций (налога на доходы физических лиц) за соответствующий налоговый период;\n\n2) возникшей в результате произведенной налогоплательщиком в соответствии с пунктом 12 статьи 10518 настоящего Кодекса обратной корректировки налоговой базы и суммы налога (убытков);\n\n3) образовавшейся у налогоплательщика в результате выполнения им письменных разъяснений о порядке исчисления и уплаты налога или по иным вопросам применения законодательства о налогах и сборах, данных ему либо неопределенному кругу лиц финансовым, налоговым или другим уполномоченным органом государственной власти (уполномоченным должностным лицом этого органа) в пределах его компетенции (указанные обстоятельства устанавливаются при наличии соответствующего документа этого органа, по смыслу и содержанию относящегося к налоговым (отчетным, расчетным) периодам, по которым образовалась недоимка, независимо от даты издания такого документа), и (или) в результате выполнения налогоплательщиком мотивированного мнения налогового органа, направленного ему в ходе проведения налогового мониторинга;\n\n4) в отношении которой принято решение о предоставлении отсрочки, рассрочки, - со дня, следующего за днем принятия указанного решения. В случае невступления решения о предоставлении отсрочки, рассрочки в силу в соответствии с пунктом 10 статьи 64 настоящего Кодекса начисление пеней возобновляется со дня, следующего за днем принятия решения о предоставлении отсрочки, рассрочки. (Дополнение подпунктом - Федеральный закон от 28.12.2022 № 565-ФЗ)\n\n(Статья в редакции  Федерального закона от 14.07.2022 № 263-ФЗ)","article_title":"Статья 75. Пеня","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9f0a78a2ba2d81f510332d94d7519b9287935b276536076654b147e055196b63"}]$law7d0062$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
